import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') {
                ptr++;
            }
            return hasNextByte();
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                c = readByte();
            }
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        if (!scanner.hasNext()) return;

        int n = scanner.nextInt();
        int t = scanner.nextInt();

        int[] type = new int[n];
        for (int i = 0; i < n; i++) {
            type[i] = scanner.nextInt();
        }

        int[] price = new int[n];
        for (int i = 0; i < n; i++) {
            price[i] = scanner.nextInt();
        }

        // Contar quantos objetos de cada tipo existem
        int[] count = new int[t + 1];
        for (int i = 0; i < n; i++) {
            count[type[i]]++;
        }

        // Offset para armazenar os objetos agrupados por tipo
        int[] head = new int[t + 2];
        for (int i = 1; i <= t; i++) {
            head[i + 1] = head[i] + count[i];
        }

        int[] cur = head.clone();
        int[] byType = new int[n];
        for (int i = 0; i < n; i++) {
            int tp = type[i];
            byType[cur[tp]++] = i;
        }

        // Ordenar cada grupo de tipo por preço crescente
        // Usamos uma ordenação auxiliar em cada fatia
        Integer[] tempOrder = new Integer[n];
        for (int i = 1; i <= t; i++) {
            int start = head[i];
            int end = head[i + 1];
            int len = end - start;
            if (len > 1) {
                for (int j = 0; j < len; j++) {
                    tempOrder[j] = byType[start + j];
                }
                Arrays.sort(tempOrder, 0, len, (a, b) -> Integer.compare(price[a], price[b]));
                for (int j = 0; j < len; j++) {
                    byType[start + j] = tempOrder[j];
                }
            }
        }

        // Ordem global para indecisos: menor preço, depois menor tipo
        Integer[] globalOrder = new Integer[n];
        for (int i = 0; i < n; i++) {
            globalOrder[i] = i;
        }
        Arrays.sort(globalOrder, (a, b) -> {
            if (price[a] != price[b]) {
                return Integer.compare(price[a], price[b]);
            }
            return Integer.compare(type[a], type[b]);
        });

        int c = scanner.nextInt();

        boolean[] sold = new boolean[n];
        int globalPtr = 0;
        int[] typePtr = head.clone();

        long totalRevenue = 0;

        for (int i = 0; i < c; i++) {
            int u = scanner.nextInt();
            if (u == 0) {
                // Cliente indeciso
                while (globalPtr < n && sold[globalOrder[globalPtr]]) {
                    globalPtr++;
                }
                if (globalPtr < n) {
                    int chosen = globalOrder[globalPtr];
                    sold[chosen] = true;
                    totalRevenue += price[chosen];
                    globalPtr++;
                }
            } else {
                // Cliente decidido pelo tipo u
                int end = head[u + 1];
                int ptr = typePtr[u];
                while (ptr < end && sold[byType[ptr]]) {
                    ptr++;
                }
                if (ptr < end) {
                    int chosen = byType[ptr];
                    sold[chosen] = true;
                    totalRevenue += price[chosen];
                    ptr++;
                }
                typePtr[u] = ptr;
            }
        }

        System.out.println(totalRevenue);
    }
}
